            path: `${CHASE_OFFERS_PATH}?${parameters}`, method: 'GET',
            headers: { 'path-params': JSON.stringify({ enterprisePartyIdentifier: session.enterprisePartyIdentifier,
                primaryDigitalAccountIdentifierList: [chaseIdentifier(accountId)] }) }
